head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var opts = {
        "id": "popup1",
        "type": "wframePopup",
        "width": "700px",
        "height": "250px",
        "top": 150,
        "left": 150,
        "popupName": "Popup_일반"
    };
    scwin.$w.openPopup("popup_useATagBtn_WEFF-403_(WSQ-3772)_sub.xml", opts);
};
scwin.ibx_openPopup2_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var opts = {
        "id": "popup_atag",
        "type": "wframePopup",
        "width": "700px",
        "height": "250px",
        "top": 450,
        "left": 150,
        "popupName": "Popup_웹접근성",
        "useATagBtn": true
    };
    scwin.$w.openPopup("popup_useATagBtn_WEFF-403_(WSQ-3772)_sub.xml", opts);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ibx_openPopup2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('popup_atag_close').innerText == '창닫기'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('popup_atag_close').style.cssText == 'text-indent: -9999px;'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
